import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BCectEOt.js";const u=JSON.parse('{"title":"About & support","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/others/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/others/"}],["meta",{"property":"og:title","content":"About & support | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Monster Hunter reference data and armor builds for Wilds, Rise with Sunbreak, and World with Iceborne."}]]},"headers":[],"relativePath":"others/index.md","filePath":"others/index.md"}'),n={name:"others/index.md"};function i(p,e,s,l,d,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="about-support" tabindex="-1">About &amp; support <a class="header-anchor" href="#about-support" aria-label="Permalink to &quot;About &amp; support&quot;">​</a></h1><h2 id="the-app" tabindex="-1">The app <a class="header-anchor" href="#the-app" aria-label="Permalink to &quot;The app&quot;">​</a></h2><p><strong>Sapphire Star Codex</strong> is an independently developed, non-commercial Monster Hunter companion from the creator of <a href="https://eurekaffeine.github.io/pocket-gallery/" target="_blank" rel="noreferrer">Pocket Gallery</a>.</p><p>It brings game-specific reference data and equipment planning into a focused native app. No ads, no paywalls.</p><p>HarmonyOS is available on <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">Huawei AppGallery</a>. iOS and Android releases are being prepared.</p><h2 id="support-the-project" tabindex="-1">Support the project <a class="header-anchor" href="#support-the-project" aria-label="Permalink to &quot;Support the project&quot;">​</a></h2><p>Optional contributions through Alipay or WeChat Pay are available on <a href="./../support/">Support us</a>. They do not unlock app features or benefits.</p><p>Help by sharing the site, checking translations, and reporting reproducible data issues. Include the game and expansion, entity name, language, expected value, and a source or steps to reproduce. Do not include personal information in screenshots.</p><p>Development and future contact channels can be found on the <a href="https://github.com/eurekaffeine" target="_blank" rel="noreferrer">developer’s public profile</a>. This website does not currently collect feedback through a form.</p><h2 id="data-and-artwork" tabindex="-1">Data and artwork <a class="header-anchor" href="#data-and-artwork" aria-label="Permalink to &quot;Data and artwork&quot;">​</a></h2><p>Game data is extracted and normalized into separate datasets for each supported game. Sources include <a href="https://docs.wilds.mhdb.io/" target="_blank" rel="noreferrer">MHDB Wilds</a>, <a href="https://mhw-db.com/" target="_blank" rel="noreferrer">MHW DB</a> and game-file extraction, with community references for cross-checking. Data can contain gaps or errors; no claim of perfect or complete coverage is made.</p><h2 id="disclaimer" tabindex="-1">Disclaimer <a class="header-anchor" href="#disclaimer" aria-label="Permalink to &quot;Disclaimer&quot;">​</a></h2><p>This is the Sapphire Star Codex project&#39;s website. The app is <strong>not affiliated with, endorsed by, or supported by CAPCOM</strong>. Monster Hunter names, designs, official icons and underlying game data belong to CAPCOM Co., Ltd. This is a non-commercial fan project. Rights-holder removal requests will be respected.</p><p>The website layout adapts Pocket Gallery’s MIT-licensed VitePress components. That code license does not apply to game artwork or game data.</p>',14)])])}const m=a(n,[["render",i]]);export{u as __pageData,m as default};
